-- TANPASISA Supabase setup
-- Jalankan seluruh file ini di Supabase SQL Editor.
-- Pastikan hanya anon/public key yang digunakan pada frontend; jangan pernah expose service_role key.

create table if not exists public.user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role in ('admin','seller','customer')),
  created_at timestamptz not null default now()
);

alter table public.user_roles enable row level security;

create or replace function public.is_tanpasisa_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.user_roles
    where user_id = auth.uid() and role = 'admin'
  );
$$;

grant execute on function public.is_tanpasisa_admin() to anon, authenticated;

drop policy if exists "Users can read their own role" on public.user_roles;
create policy "Users can read their own role"
on public.user_roles for select to authenticated
using (user_id = auth.uid() or public.is_tanpasisa_admin());

create table if not exists public.products (
  id bigint primary key,
  brand text,
  name text not null,
  category text not null,
  description text,
  price integer not null default 0,
  original_price integer not null default 0,
  stock integer not null default 0,
  expiry text,
  outlet text,
  size text,
  flavor text,
  emoji text,
  image_url text,
  image_path text,
  updated_at timestamptz not null default now()
);

alter table public.products enable row level security;

drop policy if exists "Anyone can read product catalogue" on public.products;
create policy "Anyone can read product catalogue"
on public.products for select to anon, authenticated
using (true);

drop policy if exists "Only admins can update product photos" on public.products;
create policy "Only admins can update product photos"
on public.products for update to authenticated
using (public.is_tanpasisa_admin())
with check (public.is_tanpasisa_admin());

-- Public bucket: visitors can display product images. Only authenticated Admins can upload/delete.
values ('product-images', 'product-images', true, 5242880, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set
  public = true,
  file_size_limit = 5242880,
  allowed_mime_types = array['image/jpeg','image/png','image/webp'];

drop policy if exists "Public can view product images" on storage.objects;
create policy "Public can view product images"
on storage.objects for select to public
using (bucket_id = 'product-images');

drop policy if exists "Admins can upload product images" on storage.objects;
create policy "Admins can upload product images"
on storage.objects for insert to authenticated
with check (bucket_id = 'product-images' and public.is_tanpasisa_admin());

drop policy if exists "Admins can update product images" on storage.objects;
create policy "Admins can update product images"
on storage.objects for update to authenticated
using (bucket_id = 'product-images' and public.is_tanpasisa_admin())
with check (bucket_id = 'product-images' and public.is_tanpasisa_admin());

drop policy if exists "Admins can delete product images" on storage.objects;
create policy "Admins can delete product images"
on storage.objects for delete to authenticated
using (bucket_id = 'product-images' and public.is_tanpasisa_admin());

