-- Shared order records: all dashboards read the same status in real time.
create table if not exists public.orders (
  id bigint generated by default as identity primary key,
  code text not null unique,
  user_id uuid not null references auth.users(id) on delete cascade,
  customer_email text not null,
  customer_name text not null,
  phone text,
  outlet text,
  pickup_time text,
  items jsonb not null default '[]'::jsonb,
  total integer not null default 0,
  status text not null default 'Menunggu verifikasi'
    check (status in ('Menunggu verifikasi','Terverifikasi','Ditolak')),
  rejection_reason text,
  payment text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.orders enable row level security;
drop policy if exists "Customers can create their own orders" on public.orders;
create policy "Customers can create their own orders"
on public.orders for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "Customers and admins can read orders" on public.orders;
create policy "Customers and admins can read orders"
on public.orders for select to authenticated
using (user_id = auth.uid() or public.is_tanpasisa_admin() or
 exists (select 1 from public.user_roles r where r.user_id=auth.uid() and r.role='seller'));
drop policy if exists "Admins and sellers can update order status" on public.orders;
create policy "Admins and sellers can update order status"
on public.orders for update to authenticated
using (public.is_tanpasisa_admin() or exists (select 1 from public.user_roles r where r.user_id=auth.uid() and r.role='seller'))
with check (public.is_tanpasisa_admin() or exists (select 1 from public.user_roles r where r.user_id=auth.uid() and r.role='seller'));

-- Customers and sellers need to read their own role; Admins can assign roles in Dashboard.
drop policy if exists "Users can register own role" on public.user_roles;
create policy "Users can register own role"
on public.user_roles for insert to authenticated with check (user_id = auth.uid() and role in ('customer','seller'));
drop policy if exists "Users can update own role" on public.user_roles;
create policy "Users can update own role"
on public.user_roles for update to authenticated using (user_id = auth.uid() and role in ('customer','seller'))
with check (user_id = auth.uid() and role in ('customer','seller'));

-- Realtime status propagation.
do $$
begin
  alter publication supabase_realtime add table public.orders;
exception when duplicate_object then null;
end $$;

